    /**
     * Función que se utiliza para devolver la cantidad de elementos
     *
     * @param mixed $filtrodenominacion Filtro denominación
     * @param mixed $filtrofechainicio  Filtro fecha inicio
     * @param mixed $filtrofechafin     Filtro fecha fin
     * @param mixed $filtrocodigo       Filtro código
     * @param mixed $filtrosiglas       Filtro siglas
     *
     * @return int
     * @throws Doctrine_Exception
     */
    static function cantidad($filtrodenominacion, $filtrofechainicio, $filtrofechafin, $filtrocodigo, $fitrosiglas)
    {
        try {
            $query = Doctrine_Query::create();
            $datos = $query->from('NomPais');
            $datos = ($filtrodenominacion != '') ? $datos->addWhere("lower(nombrepais) LIKE '%$filtrodenominacion%'")
                : $datos;
            $datos = ($filtrocodigo != '') ? $datos->addWhere("lower(codigopais) LIKE '%$filtrocodigo%'") : $datos;
            $datos = ($fitrosiglas != '') ? $datos->addWhere("lower(siglas) ILIKE '%$fitrosiglas%'") : $datos;
            $datos = self::filtroFecha($filtrofechainicio, $filtrofechafin, $datos);
            $final = $datos->count();
            return $final;
        } catch (Doctrine_Exception $ee) {

            return false;
        }
    }

    /**
     * Comparte las funcionalidades cantidad y valor
     *
     * @param mixed $filtrofechainicio  Filtro fecha inicio
     * @param mixed $filtrofechafin     Filtro fecha fin
     * @param query $datos
     *
     * @return query $dat
     */
    private function filtroFecha($filtrofechainicio, $filtrofechafin, $datos)
    {
        $dat = $datos;
        if (($filtrofechainicio != '') && ($filtrofechafin != '')) {
            $dat = $dat->addWhere(
                "fechainicio >= '$filtrofechainicio' AND fechafin <='$filtrofechafin'"
            );
        } else {
            $dat = ($filtrofechainicio != '') ? $dat->addWhere("fechainicio='$filtrofechainicio'") : $dat;
            $dat = ($filtrofechafin != '') ? $dat->addWhere("fechafin='$filtrofechafin'") : $dat;
        }
        return $dat;
    }

    /**
