     * @param mixed $fitrosiglas        Filtro siglas
     *
     * @return array
     * @throws Doctrine_Exception
     */
    static function valores(
        $limit, $start, $filtrodenominacion, $filtrofechainicio, $filtrofechafin, $filtrocodigo, $fitrosiglas
    )
    {
        try {
            $query = Doctrine_Query::create();
            $datos = $query->select('*')->from('NomPais')->limit($limit)->offset($start);
            $datos = ($filtrodenominacion != '') ? $datos->addWhere("lower(nombrepais) LIKE '%$filtrodenominacion%'")
                : $datos;
            $datos = ($filtrocodigo != '') ? $datos->addWhere("lower(codigopais) LIKE '%$filtrocodigo%'") : $datos;
            $datos = ($fitrosiglas != '') ? $datos->addWhere("lower(siglas) ILIKE '%$fitrosiglas%'") : $datos;
            $datos = self::filtroFecha($filtrofechainicio, $filtrofechafin, $datos);
            $final = $datos->orderBy('nombrepais')->execute()->toArray();
            return $final;
        } catch (Doctrine_Exception $ee) {
            return false;
        }
    }

