    /**
     * Función que se utiliza para devolver los paises repetidos.
     *
     * @param string $nombrepais Nombre del país
     * @param int    $codigopais Código del país
     *
     * @return array
     */
    static function comprobarElementorepetido($nombrepais, $codigopais)
    {
        $aux = preg_replace('/\s+/', ' ', $nombrepais);
        $auxDos = preg_replace('/\s+/', ' ', $codigopais);
        $q = new Doctrine_Query();
        $valores = $q->from('NomPais n')
            ->where("lower(n.nombrepais) LIKE lower(trim('$aux')) and lower(n.codigopais) LIKE lower(trim('$auxDos'))")
            ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
            ->execute();
        return $valores;
    }

