    /**
     * Obtener el nomenclador de Pa&iacute;ses.
     *
     * @param array $argFilterSql Arreglo de condiciones para filtrar los pa&iacute;ses.
     *
     * @throws Doctrine_Exception $ee Excepci&oacute;n de doctrine ocurrida durante la transacci&oacute;n.
     * @return bool Devuelve verdadero si fue realizada la operaci&oacute;n, falso de lo contrario.
     */
    static public function obtenerNomPaises($argFilterSql = array())
    {
        try {
            $query = new Doctrine_Query();
            if (count($argFilterSql) > 0) {
                $query->addWhere("UPPER(nombrepais) LIKE '%" . strtoupper($argFilterSql ['nombrepais']) . "%'");
            }
            $paises = $query
                ->from('NomPais')
                ->orderBy('nombrepais')
                ->setHydrationMode(Doctrine_Core::HYDRATE_ARRAY)
                ->execute();
            return $paises;
        } catch (Doctrine_Exception $ee) {
            throw $ee;
        }
    }

    /**
     * Obtener el nomenclador de Pa&iacute;ses.
     *
     * @param array $cond  Arreglo de condiciones
     * @param int   $limit Límite superior
     * @param int   $start Comienzo inferior
     *
     * @throws Doctrine_Exception
     * @return array
     */
    public function buscar($cond = array(), $limit = 10, $start = 0)
    {
        try {
            $filter = " 0 = 0 ";
            if ($cond['idpais']) {
                $filter .= "e.idpais = '" . $cond['idpais'] . "'";
            }
            if ($cond['codigopais']) {
                $filter .= " and e.codigopais = '" . $cond['codigopais'] . "'";
            }
            if ($cond['nombrepais']) {
                $filter .= " and lower(e.nombrepais) = '" . strtolower($cond['nombrepais']) . "'";
            }
            $q = new Doctrine_Query();
            if ($filter) {
                $estudiante = $q->from('NomPais e')->where($filter)->execute();
                $estudiant = $q->from('NomPais e')->where($filter)->limit($limit)->offset($start)->execute();
            } else {
                $estudiante = $q->from('NomPais e')->execute();
                $estudiant = $q->from('NomPais e')->limit($limit)->offset($start)->execute();
            }
            $estudiantes = $estudiant->toArray();

            $resultado = array('cant' => $estudiante->count(), 'datos' => $estudiantes);
            return $resultado;
        } catch (Doctrine_Exception $ee) {
            return false;
        }
    }

    /**
     * Devuelve un listado de todos los paises de la tabla nom_paises
     *
     * @author Jorge Luis Cuellar Mondeja
     *
     * @param int   $limit Límite superior
     * @param int   $start Comienzo inferior
     * @param mixed $where
     *
     * @date 22/07/2013
     * @return array
     */
    public function getPaises($start, $limit, $where)
    {

        $query = new Doctrine_Query();
        $query->from('NomPais');

        if ($where) {
            $query->addWhere($where);
        }

        if ($limit) {
            $query->offset($start);
            $query->limit($limit);
        }
        $query->orderBy('nombrepais');
        return $query->fetchArray();
    }

