    /**
     *
     * Verifica al modificar un pais, si existe otro pais con el mismo codigo, denominacion o sigla igual a pesar de el.
     *
     * @param object $objNomPais objeto NomPais a modificar.
     *
     * @return code Código -1 si se puede modificar -5 si se encuentra otro pais con su denominacion -2
     * si se encuentra otro pais con el mismo codigo -3 con la misma sigla.
     * @throws Doctrine_Exception
     */
    static function verificarModpais($objNomPais)
    {
        $idpais = $objNomPais->idpais;
        $codigopais = $objNomPais->codigopais;
        $siglas = $objNomPais->siglas;
        $nombrepais = $objNomPais->nombrepais;
        try {
            $query = Doctrine_Query::create();
            $nombrePais = $query->select('np.idpais')
                ->from('NomPais np')
                ->where("np.nombrepais iLIKE '$nombrepais'  AND np.idpais <> '$idpais'")
                ->setHydrationMode(Doctrine_Core::HYDRATE_RECORD)
                ->execute();
            //$query1 = Doctrine_Query::create();
            $codigoPais = $query->select('np.idpais')
                ->from('NomPais np')
                ->where("np.codigopais = '$codigopais'  AND np.idpais <> '$idpais'")
                ->setHydrationMode(Doctrine_Core::HYDRATE_RECORD)
                ->execute();
            //$query2 = Doctrine_Query::create();
            $siglasPais = $query->select('np.idpais')
                ->from('NomPais np')
                ->where("np.siglas iLIKE '$siglas'  AND np.idpais <> '$idpais'")
                ->setHydrationMode(Doctrine_Core::HYDRATE_RECORD)
                ->execute();
            if ($nombrePais->count() > 0) {
                return -5;
            } elseif ($codigoPais->count() > 0) {
                return -3;
            } elseif ($siglasPais->count() > 0) {
                return -6;
            }
            return -1;
        } catch (Doctrine_Exception $ee) {
            throw $ee;
        }
    }

    /**
     *Obtiene los pa&iacute; del nomenclador
     * @param array $argFilterSql Utilizado para la busqueda en la forma array('nombrepais' => 'miPais')
     * @param int   $start Inicio inferior
