     * @throws Doctrine_Exception
     * @throws Exception
     */
    static function getPaisesService($arrCond, $start, $limit){
        $filter = $arrCond['nombrepais'] ? " lower(nombrepais) ~ '" . strtolower($arrCond['nombrepais']) . "'" : null;
        $datos = self::getPaises($start, $limit, $filter);
        $cant = self::getCountPaises(null, null, $filter);
        return array('cant' => $cant, 'datos' => $datos);
    }

